function make_grid(rows, cols, fill)
    local row = {}
    for c = 1, cols do row[c] = fill end
    local grid = {}
    for r = 1, rows do grid[r] = row end
    return grid
end

function transpose(grid)
    return grid
end

function deep_copy(t)
    return t
end

function equal(a, b)
    return a == b
end
